const { chromium } = require('C:\\\\Users\\\\gosts\\\\AppData\\\\Roaming\\\\npm\\\\node_modules\\\\playwright');
(async()=>{const b=await chromium.launch({headless:true}); const out={};
async function p(n){let x=await b.newPage({viewport:{width:1100,height:900}}); await x.goto("'`http://localhost:8141/embeds/abap/CH16-L${String(n).padStart(2,'"'0')}-S01.html"'`,{waitUntil:'"'networkidle'}); return x;}
let x=await p(3); await x.locator('[data-f=gv_conc]').fill('C002'); await x.locator('[data-f=gv_seats]').fill('3'); await x.locator('[data-f=gv_vip]').check(); await x.locator('[data-f=gv_stat]').selectOption('W'); await x.locator('[data-fct=SAVE]').click(); out.L03=await x.locator('[data-mon]').innerText(); await x.close();
x=await p(5); await x.locator('#ihpConc').selectOption('C001'); await x.locator('[data-act=f4]').click(); out.L05={steps:await x.locator('#ihpSteps').innerText(),choices:await x.locator('#ihpPopup').innerText()}; await x.close();
x=await p(6); await x.locator('.pps-lock [data-v=\"1\"]').click(); for(let i=0;i<5;i++) await x.locator('[data-next]').click(); out.L06=await x.locator('#ppsStatus').innerText(); await x.close();
x=await p(7); await x.locator('.obl-clear [data-v=\"0\"]').click(); await x.locator('[data-fct=SAVE]').click(); await x.locator('[data-enter]').click(); out.L07=await x.locator('#oblTrace').innerText(); await x.close();
x=await p(8); await x.locator('.tfm-lock [data-v=\"1\"]').click(); out.L08={saveDisabled:await x.locator('[data-fct=SAVE]').isDisabled(),status:await x.locator('#tfmStatus').innerText()}; await x.close();
x=await p(9); await x.locator('#sedPanel .sed-seg [data-bad=\"1\"]').click(); out.L09=await x.locator('#sedPanel').innerText(); await x.close();
x=await p(10); await x.locator('[data-seats]').fill('6'); await x.locator('[data-fct=SAVE]').click(); let over=await x.locator('#dfsMsg').innerText(); await x.locator('[data-fct=ENTER]').click(); let enter=await x.locator('#dfsMsg').innerText(); out.L10={statusOptions:await x.locator('[data-stat] option').allTextContents(),over,enter,fields:await x.locator('.dfs-form').innerText()}; await x.close();
console.log(JSON.stringify(out,null,2)); await b.close();})().catch(e=>{console.error(e);process.exit(1)});
